/* Owner-approved SDCE print design (2026-11-09): the standard Frappe print look. Colours are the Frappe v16
   print greys as literal hex (no CSS variables, @import or remote fonts: wkhtmltopdf's old Qt WebKit drops
   them): text #171717, secondary #525252, labels #7c7c7c, table header #f3f3f3, borders #d1d8dd, light
   separators #ededed, heading underline #aaa. Bundled app font plus the legacy .print-format override that
   lets the content own the full printable width. */
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Bold.ttf'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Bold.ttf'); font-weight: bold; font-style: normal; }

.print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
.print-format-gutter { padding: 0 !important; }

/* text-rendering auto: frappe's print bundle sets optimizeLegibility on body,
   which makes Qt draw RTL lines wider than it measures them (text crosses cell
   borders); resetting it here fixes the geometry. */
.emc { text-rendering: auto; font-family: 'Noto Sans Arabic', 'Card Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; font-size: 9pt; line-height: 1.4; color: #171717; width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.emc table { width: 100%; border-collapse: collapse; margin: 0; }
.emc th, .emc td { word-wrap: break-word; }
/* old Qt WebKit (wkhtmltopdf) follows CSS direction, not the dir attribute, and has no text-align: start */
.emc.rtl { direction: rtl; text-align: right; }
.emc.ltr { direction: ltr; text-align: left; }

.emc-lh { margin-bottom: 3mm; text-align: center; }
.emc-lh img { max-height: 22mm; max-width: 100%; }

.emc-co { font-size: 10pt; font-weight: bold; color: #525252; margin: 0 0 1px; }
.emc-title { border-bottom: 1px solid #aaa; margin: 0 0 2.5mm; padding-bottom: 3px; }
.emc-title h2 { margin: 0; font-size: 16pt; font-weight: bold; color: #171717; line-height: 1.3; }
.emc-title h2 .st { color: #7c7c7c; font-size: 11pt; }

/* no rowspan: Qt WebKit misplaces auto-layout columns next to a rowspan cell,
   so the image sits in its own cell of an outer wrapper table instead. */
.emc-head-outer { margin-bottom: 2.5mm !important; }
.emc-head-outer td.ehc { border: none !important; padding: 0 !important; vertical-align: top; }
.emc-meta { table-layout: fixed; }
.emc-meta td { border: none !important; padding: 0.6mm 1mm !important; vertical-align: top; color: #171717; }
.emc-meta td.ml { width: 13%; font-weight: bold; color: #7c7c7c; }
.emc.rtl .emc-meta td { text-align: right; }
.emc.ltr .emc-meta td { text-align: left; }
.emc-meta .nw { white-space: nowrap; }
.emc-img { width: 15%; border: 1px solid #d1d8dd !important; text-align: center; vertical-align: middle; padding: 1mm !important; }
.emc-img img { max-width: 100%; max-height: 24mm; }

.emc-days-wrap td.emc-half { width: 50%; vertical-align: top; padding: 0 0.8mm !important; border: none !important; }
.emc-days { table-layout: fixed; border: 1px solid #d1d8dd; }
.emc-days th, .emc-days td { border: 1px solid #d1d8dd !important; padding: 0 2px !important; text-align: center; vertical-align: middle; height: 5.4mm; font-size: 8pt; overflow: hidden; }
.emc-days th { background: #f3f3f3 !important; color: #525252; font-weight: bold; padding: 1mm 1px !important; font-size: 7.5pt; }
.emc.rtl .emc-days td.t { text-align: right; }
.emc.ltr .emc-days td.t { text-align: left; }
.emc-days td.c { direction: ltr; unicode-bidi: embed; white-space: nowrap; }
.emc-days td.num { direction: ltr; unicode-bidi: embed; white-space: nowrap; text-align: right; }
.emc-days tr.fri td { background: #fafafa !important; }
.emc-days tr.off td { color: #7c7c7c; }

/* the settlement block: additions/deductions rows at the start side, the totals right next to their
   amount column at the end side of the page, as in a standard invoice */
.emc-sum { margin-top: 3mm !important; table-layout: fixed; }
.emc-sum td.emc-sum-s { width: 40%; vertical-align: top; border: none !important; padding: 0 !important; }
.emc-sum td.emc-sum-g { width: 2%; border: none !important; padding: 0 !important; }
.emc-sum td.emc-sum-m, .emc-sum td.emc-sum-e { width: 28%; vertical-align: top; border: none !important; padding: 0 !important; }
.emc-cap { font-weight: bold; color: #525252; padding: 0 1mm 1mm; border-bottom: 1px solid #aaa; margin-bottom: 0; }

.emc-adj { table-layout: fixed; border: 1px solid #d1d8dd; }
.emc-adj th, .emc-adj td { border: 1px solid #d1d8dd !important; padding: 0.8mm 1mm !important; vertical-align: middle; font-size: 8pt; overflow: hidden; }
.emc-adj th { background: #f3f3f3 !important; color: #525252; font-weight: bold; text-align: center; }
.emc.rtl .emc-adj td { text-align: right; }
.emc.ltr .emc-adj td { text-align: left; }
.emc-adj td.c { text-align: center !important; }
.emc-adj td.num { direction: ltr; unicode-bidi: embed; white-space: nowrap; text-align: right !important; }

/* one weight per cell: Qt overlaps a regular+bold Arabic run pair */
.emc-tot { margin-bottom: 2.5mm !important; page-break-inside: avoid; }
.emc-tot th { color: #525252; font-weight: bold; padding: 0 1mm 1mm !important; border-bottom: 1px solid #aaa !important; }
.emc-tot td { padding: 0.7mm 1mm !important; border-bottom: 1px solid #ededed !important; vertical-align: middle; }
.emc-tot td.k { width: 58%; color: #525252; }
.emc-tot td.v { direction: ltr; unicode-bidi: embed; font-weight: bold; white-space: nowrap; }
.emc.rtl .emc-tot th, .emc.rtl .emc-tot td.k { text-align: right; }
.emc.ltr .emc-tot th, .emc.ltr .emc-tot td.k { text-align: left; }
.emc.rtl .emc-tot td.v { text-align: left; }
.emc.ltr .emc-tot td.v { text-align: right; }
.emc-tot tr.last td { font-size: 10pt; font-weight: bold; color: #171717; border-top: 1px solid #aaa !important; border-bottom: none !important; }

.emc-notes { margin-top: 2mm; padding: 1mm 0; border-top: 1px solid #ededed; }
.emc-notes .ml { font-weight: bold; color: #7c7c7c; }

.emc-sign { margin-top: 5mm !important; table-layout: fixed; page-break-inside: avoid; }
.emc-sign td { width: 33%; text-align: center !important; padding: 0 5mm !important; border: none !important; vertical-align: top; }
.emc-sign .l { border-top: 1px solid #999; margin: 9mm 8% 1.2mm; height: 0; }
.emc-sign .t { font-weight: bold; color: #525252; }
.emc-sign .n { color: #171717; min-height: 4mm; }
